function scoreLabel(score){return Number.isFinite(score)?score+'%':'Not scored';}
(function(){
'use strict';
const M=DeltaModel,GUIDED=document.body.dataset.guided==='true',KEY=GUIDED?'finsyndeo-whole-review-platform-walkthrough-v1':'finsyndeo-whole-review-incremental-review-v1',UIKEY=KEY+'-ui',q=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)],esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let saved=null,ui={role:'applicant',actor:'C1',view:'results',sort:'match',provider:'P14',request:null,report:null,compare:[],drafts:{}};
try{saved=JSON.parse(localStorage.getItem(KEY)||'null');const u=JSON.parse(localStorage.getItem(UIKEY)||'null');if(u)ui={...ui,...u};}catch(e){}
if(GUIDED&&!window.WholeInit?.token){ui.role='applicant';ui.actor='C1';ui.view='results';}
let store=new M.Store(saved?.version===1?saved:null);try{store.login(ui.role,ui.actor);}catch(e){ui.role='applicant';ui.actor='C1';store.login('applicant','C1');}
const views={applicant:{results:'Your solutions',requests:'My introductions',alerts:'Match notifications'},admin:{scenarios:'Scenarios A–J',settings:'Introduction & pricing',entitlements:'Entitlements & decisions',providers:'Provider commercial profile',ratings:'External ratings',reportsettings:'Provider report controls',ledger:'Applicant payment ledger',notifications:'Notification history',audit:'Audit trail'},provider:{preferences:'Reporting preferences',reports:'My reports'},introducer:{impact:'Introducer impact'}};
const draftKey=()=>ui.role+':'+ui.actor+':'+ui.view+(['providers','ratings','reportsettings'].includes(ui.view)?':'+ui.provider:'');
const displayDate=d=>/^\d{4}-\d{2}-\d{2}$/.test(d||'')?new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'long',year:'numeric',timeZone:'Europe/Bucharest'}).format(new Date(d+'T12:00:00Z')):d;
const appId=()=>ui.application||(ui.actor==='C2'?'A2':'A1'),client=()=>store.s.clients.find(c=>c.id===ui.actor),fmt=(n,c)=>M.money(n,c),field=(id,label,val,type='text',attrs='')=>`<label class="field"><span>${esc(label)}</span><input id="${id}" name="${id}" type="${type}" value="${esc(val)}" ${attrs}></label>`,select=(id,label,val,opts)=>`<label class="field"><span>${esc(label)}</span><select id="${id}" name="${id}">${opts.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${v===val?'selected':''}>${esc(l)}</option>`;}).join('')}</select></label>`,check=(id,label,on)=>`<label class="checkline"><input id="${id}" name="${id}" type="checkbox" ${on?'checked':''}>${esc(label)}</label>`,button=(action,label,data='',primary=false)=>`<button type="button" data-action="${action}" ${data} class="${primary?'primary':''}">${esc(label)}</button>`,head=(title,lead='')=>`<h1>${esc(title)}</h1>${lead?`<p class="lead page-description">${esc(lead)}</p>`:''}`;
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map((cell,i)=>`<td data-label="${esc(headers[i])}"><span>${cell}</span></td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(store.s));localStorage.setItem(UIKEY,JSON.stringify(ui));}catch(e){message('Browser storage is unavailable. Keep this page open and export your records.',true);}}
function message(text,error=false){q('#feedback').hidden=false;q('#feedback').className=error?'error':'';q('#feedback').textContent=text;}
function go(view){ui.view=view;save();render();window.scrollTo(0,0);}
function summary(app){const a=store.app(app),t=store.s.settings,n=store.free(a.client),reserved=store.s.requests.filter(r=>r.client===a.client&&r.entitlement==='reserved'&&r.grant).length;return `<div class="metricbar"><div><span>Free introductions available</span><strong>${t.free?n:'Unlimited'}</strong>${reserved?`<small>${reserved} reserved pending a decision</small>`:''}</div><div><span>Next free introduction</span><strong style="font-size:16px">${esc(displayDate(store.nextGrant(a.client))||'No recurring allowance')}</strong></div><div><span>Additional introduction</span><strong>${t.paid?fmt(t.fee,t.currency):'Paid introductions off'}</strong></div></div>`;}
function alertForm(){const a=store.app(appId());return `<form id="alert-form" class="panel alert-panel"><div><h2>Keep me informed of new matches</h2>${check('alerts-enabled','Notify me when a new provider fits my requirements.',a.alerts.enabled)}<p class="hint">You can turn notifications off at any time. Essential requirements must still be met.</p></div><div>${select('threshold','Minimum match',String(a.alerts.threshold),[['80','80%+'],['85','85%+'],['90','90%+'],['95','95%+'],['100','100%']])}<button class="primary">Save preference</button></div></form>`;}
function existingRequest(provider){return store.s.requests.find(r=>r.client===ui.actor&&r.app===appId()&&r.provider===provider&&!['Rejected','Cancelled'].includes(r.status));}
function compareCards(){const rows=store.result(appId()).filter(r=>(ui.compare||[]).includes(r.provider));if(rows.length<2)return head('Choose at least two solutions')+button('back-results','Back to results');return head('Compare your selected solutions','Choose the provider whose available service and introduction terms suit your needs.')+`<div class="cards compare-cards">${rows.map(r=>`<section class="card"><h2>${esc(r.code)}</h2><dl><dt>FinSyndeo match</dt><dd>${scoreLabel(r.score)}</dd><dt>Service</dt><dd>${esc(r.service)}</dd><dt>Jurisdiction</dt><dd>${esc(r.country)}</dd><dt>External rating</dt><dd>${esc(r.rating.label)}</dd><dt>Introduction fee</dt><dd>${r.quote.blocked?'Review required':r.quote.amount?fmt(r.quote.amount,r.quote.currency):'Free'}</dd></dl>${button('details','Review this solution',`data-provider="${r.provider}"`,true)}</section>`).join('')}</div><div class="form-actions">${button('back-results','Back to all results')}</div>`;}
function results(){const a=store.app(appId()),rows=store.result(a.id,ui.sort);ui.compare=(ui.compare||[]).filter(id=>rows.some(r=>r.provider===id));return head('Your potential providers','Compare the matches below, then review a solution to request an introduction.')+summary(a.id)+(GUIDED&&store.free(a.client)===0?'<div class="notice"><b>Your free introduction allowance has been used.</b> Review the introduction fee shown for each available solution before proceeding.</div>':'')+`<div class="toolbar"><span>${rows.length} potential providers</span>${select('sort','Sort by',ui.sort,[['match','Highest FinSyndeo match'],['rating','External rating band'],['country','Jurisdiction'],['fee','Applicant fee — grouped by currency']])}</div><div class="cards">${rows.map(r=>{const current=existingRequest(r.provider);return `<article class="card"><div class="card-head"><div><h2>${esc(r.code)}</h2><span class="pill">${esc(r.service)}</span></div><div class="fit">${scoreLabel(r.score)}<div style="font-size:11px;font-weight:400">FinSyndeo match</div></div></div><dl><dt>Jurisdiction</dt><dd>${esc(r.country)}</dd><dt>External rating</dt><dd>${esc(r.rating.label)}</dd><dt>Introduction fee</dt><dd>${current?'Already requested':r.quote.blocked?'SOPHIMA review':r.quote.amount?fmt(r.quote.amount,r.quote.currency):'Free'}</dd></dl><p class="hint">${esc(current?current.status:r.quote.blocked?r.quote.message:r.quote.reason)}</p>${current?button('go-requests','View my introduction'):button('details','View details & choose',`data-provider="${r.provider}"`,true)}<label class="checkline compare-choice"><input type="checkbox" data-compare="${r.provider}" ${ui.compare.includes(r.provider)?'checked':''}>Compare this solution</label></article>`;}).join('')}</div><div class="form-actions">${button('compare','Compare selected ('+ui.compare.length+')')}<span class="hint">Select two or three solutions to compare.</span></div>`+alertForm()+`<p class="disclaimer">Potential fit is not account approval. Fees and external rating bands do not change your match score. Provider names remain confidential.</p>`+(GUIDED?`<details class="demo-actions"><summary>Try the notification example</summary><p>Save a 90% threshold above, then make the sample 93% provider available. A 95% threshold will not trigger this example.</p>${button('demo-new-provider','Make sample 93% provider available')}<p class="hint">This runs the sample checks only; no email is sent. Restart the client example to repeat the test.</p></details><div class="sample-notifications">${store.s.notifications.filter(n=>n.client===ui.actor).map(n=>`<section class="notice"><b>Notification example · ${esc(n.status)}</b><p>${esc(n.message)}</p></section>`).join('')}</div>`:'');}
function details(){const r=store.result(appId()).find(r=>r.provider===ui.provider);if(!r)return head('This solution is currently unavailable')+button('back-results','Back to solutions');return head(r.code+' · '+r.service,'Review the introduction terms before requesting this solution.')+`<section class="panel"><div class="grid"><div><h2>FinSyndeo match ${scoreLabel(r.score)}</h2><p>${esc(r.country)} · External rating: ${esc(r.rating.label)}</p><p>Confirmed coverage in this fictional snapshot: ${r.coverage}%.</p></div><div><h2>Introduction fee</h2><strong>${r.quote.blocked?'SOPHIMA review required':r.quote.amount?fmt(r.quote.amount,r.quote.currency):'Free'}</strong><p>${esc(r.quote.reason||r.quote.message)}</p></div></div><p class="hint">An introduction is used when the provider gives a genuine positive response allowing onboarding to proceed. If you then choose not to proceed, it remains used. A response is not final account approval.</p>${r.quote.amount?'<p class="hint">If the provider declines before this stage, the payment goes to refund/credit review. Final terms are subject to approval.</p>':''}${check('intro-terms','I have reviewed the introduction terms and authorise SOPHIMA to proceed.',false)}<div class="form-actions">${button('back-results','Back')}${button('request',r.quote.amount?'Continue to checkout':'Request introduction',`data-provider="${r.provider}"`,true)}</div></section>`;}
function chargeExplanation(quote){return quote.nonrem?'This solution has a provider-specific introduction fee. Your general free credits remain available for other qualifying solutions.':quote.extra?'Your general free introduction allowance has been used.':'';}
function checkout(){const r=store.requestOwner(ui.request);if(r.quote.kind!=='paid')return requests();const price=r.quote;return head('Review your introduction payment','No live gateway is connected. Use the sample payment controls below.')+`<section class="panel"><h2>${esc(store.provider(r.provider).code)}</h2><div class="summaryline"><span>Introduction fee</span><strong>${fmt(price.net,price.currency)}</strong></div><div class="summaryline"><span>VAT / tax (${esc(price.taxMode)})</span><strong>${fmt(price.tax,price.currency)}</strong></div><div class="summaryline"><span>Total payable</span><strong>${fmt(price.amount,price.currency)}</strong></div><p>${esc(price.reason)}</p><p class="hint">${esc(chargeExplanation(price))}</p><p class="hint">Only one introduction fee applies, including when both charging conditions are met. Payment does not guarantee pre-approval or replace SOPHIMA's checks.</p><div class="payment-method"><b>Secure payment</b><p>Card payment · sample checkout</p><span class="pill">Demo card ending 4242</span><small>No real card details are requested or stored.</small></div><span class="pill">${esc(r.paymentStatus)}</span><p class="hint">${price.taxMode==='none'?'No VAT applied in this fictional quote. Actual tax treatment must be approved before launch.':''}</p>${r.status==='Awaiting payment'?`<div class="form-actions">${button('pay-success',`Simulate payment — ${fmt(price.amount,price.currency)}`,`data-id="${r.id}"`,true)}${button('pay-pending','Simulate pending',`data-id="${r.id}"`)}${button('pay-failed','Simulate failed',`data-id="${r.id}"`)}</div>`:''}<div class="form-actions">${button('go-requests','My introductions')}</div></section>`;}
function paymentSuccess(){const r=store.requestOwner(ui.request),p=store.s.payments.find(p=>p.request===r.id&&p.status==='Payment Successful')||store.s.payments.find(p=>p.app===r.app&&p.provider===r.provider&&p.status==='Payment Successful');return head('Introduction payment received','Your request has been recorded for SOPHIMA review.')+`<section class="panel"><span class="pill status-positive">Sample payment successful</span><h2>${esc(store.provider(r.provider).code)}</h2><div class="summaryline"><span>Total paid</span><strong>${fmt(r.quote.amount,r.quote.currency)}</strong></div><div class="summaryline"><span>Receipt reference</span><strong>${esc(p?.receipt||'Demo receipt')}</strong></div><p>Payment does not guarantee account approval. SOPHIMA must complete the applicable checks before an introduction proceeds.</p><div class="form-actions">${button('go-requests','View my introductions','',true)}${button('back-results','Back to results')}</div></section>`;}
function requests(){const rows=store.s.requests.filter(r=>r.client===ui.actor);return head('My introductions','Requested introductions reserve a credit. Pre-approval consumes it.')+summary(appId())+(!rows.length?'<div class="empty">No introductions requested yet. Choose a potential provider to begin.</div>':'')+rows.map(r=>`<section class="listitem"><h3>${esc(store.provider(r.provider).code)} · ${esc(r.id)}</h3><div class="grid"><div><p>${esc(r.status)}</p><p class="hint">Entitlement: ${esc(r.entitlement)}${r.consumed?' · used '+r.consumed:''}</p></div><div><p>${esc(r.paymentStatus)}${r.quote.amount?' · '+fmt(r.quote.amount,r.quote.currency):''}</p><p class="hint">${esc(r.quote.reason)}</p></div></div><div class="row-actions">${r.status==='Awaiting payment'?button('checkout','Open checkout',`data-id="${r.id}"`):''}${r.status==='Pre-approved — onboarding may proceed'?button('withdraw','I choose not to proceed',`data-id="${r.id}"`):''}${['Awaiting payment','Introduction Requested','Introduced to provider'].includes(r.status)?button('cancel','Cancel request',`data-id="${r.id}"`):''}</div></section>`).join('')+`<section class="panel"><h2>Paid introduction credits</h2>${store.s.paidCredits.filter(c=>c.client===ui.actor).map(c=>`<p>${fmt(c.amount,c.currency)} · ${c.used?'Used':c.reserved?'Reserved':'Available'} · ${esc(c.id)}</p>`).join('')||'<p class="hint">No paid replacement credits.</p>'}</section>`;}
function alerts(){return head('New-provider notifications','Manage notifications for your saved assessment.')+alertForm()+`<h2>Notification history</h2>${store.s.notifications.filter(n=>n.client===ui.actor).map(n=>`<section class="listitem"><p>${esc(n.message)}</p><small>${n.date} · ${esc(n.status)}</small></section>`).join('')||'<p class="hint">No notifications generated yet.</p>'}`;}
const scenarios=[['A','First applicant','One positive response: 3 free → 2 available.'],['B','Provider rejection','A reserved free introduction is released.'],['C','Client withdrawal','Pre-approval followed by withdrawal remains used.'],['D','Fourth introduction','Free allowance exhausted; checkout EUR 250.'],['E','Non-remunerating provider','EUR 250 applies; general free credits remain.'],['F','Both conditions','Exhausted allowance + provider fee = EUR 250 once.'],['G','Monthly allowance','Advance to 1 November: a new free credit.'],['H','New match notification','Threshold 90%; newly eligible match 93%.'],['I','External rating band','Admin sees 4.78; applicant sees 4.5+/5.'],['J','Provider reports','Quarterly report and an ad hoc report.']];
function adminScenarios(){return head('Review scenarios A–J','Each button resets only this incremental sample and prepares that scenario. Earlier packages are unaffected.')+`<div class="scenario-grid">${scenarios.map(([id,name,note])=>`<button data-action="scenario" data-key="${id}"><b>${id} · ${esc(name)}</b><small>${esc(note)}</small></button>`).join('')}</div><section class="panel"><h2>Review guidance</h2><p>Switch perspectives in the review bar. The Applicant sees only anonymous solutions; the Provider sees its own case reports; Introducer impact preserves the existing provider-commission rules.</p><p class="hint">Pre-approval fixtures represent a human provider decision. No actual DD, screening or matching is performed.</p><a href="REVIEW-NOTES.html">Read impact review, model delta and decisions</a></section>`;}
function settings(){const t=store.s.settings;return head('Introduction & pricing settings','Changes apply to future quotes/grants. Existing charges retain their recorded terms.')+`<form id="settings-form"><section class="panel"><h2>Free introduction allowance</h2>${check('free','Free introduction system enabled',t.free)}<div class="grid">${field('initial','Initial free introductions — new clients',t.initial,'number','min="0" max="100" required')}${field('recurring-count','Recurring free introductions',t.recurringCount,'number','min="0" max="100" required')}</div>${check('recurring','Recurring free introductions enabled',t.recurring)}<div class="grid">${select('frequency','Recurring frequency',t.frequency,[['monthly','Monthly'],['cycle','Per approved application cycle'],['interval','Other — interval in days']])}${field('interval','Days for other frequency',t.intervalDays,'number','min="1" max="366" required')}</div>${check('accumulate','Unused recurring credits accumulate',t.accumulate)}<p class="hint">Otherwise recurring credits expire at the next period. Initial credits do not expire. The initial allowance is awarded once per canonical client.</p></section><section class="panel"><h2>Paid introductions</h2>${check('paid','Paid introductions enabled',t.paid)}${check('checkout','Online checkout enabled',t.checkout)}${check('nonrem','Charge for non-remunerating providers when their fee is enabled',t.nonremCharge)}<div class="grid">${field('fee','Standard additional introduction fee',t.fee/100,'number','min="0" step="0.01" required')}${select('currency','Default currency',t.currency,['EUR','GBP','USD','CHF'])}${select('tax','VAT / tax treatment',t.tax,[['none','No VAT applied — approved basis required'],['included','VAT included in fee'],['added','VAT added to fee'],['manual','Hold for tax review']])}${field('tax-rate','VAT rate (%) — reviewed configuration',t.taxRate,'number','min="0" max="100" step="0.01" required')}</div>${select('refund','Suggested rejection handling — final policy pending',t.refund,[['manual','SOPHIMA decides manually'],['refund','Refund recommended'],['credit','Offer replacement credit']])}<p class="hint">Paid OFF preserves free quota; exhausted clients wait for a grant/SOPHIMA review. Disable quota as well for an unlimited free model. Existing payments still require resolution.</p></section><section class="panel"><h2>Optional features</h2>${check('alerts-feature','Applicant new-provider alerts',t.alerts)}${check('ratings-feature','External rating bands',t.ratings)}${field('rating-days','Maximum rating age in days',t.ratingMaxAgeDays,'number','min="1" max="730" required')}${check('reports-feature','Provider reports enabled',t.reports)}${check('scheduled-feature','Provider scheduled reports enabled',t.scheduledReports)}</section><section class="panel">${field('settings-reason','Reason for changes','','text','required')}<button class="primary">Save settings</button></section></form>`;}
function entitlements(){return head('Entitlements & provider decisions','Record evidenced pre-approval or rejection. Payment and verification gates still apply.')+`<form id="clock-form" class="panel"><h2>Sample clock</h2>${field('new-date','Advance sample date',store.s.date,'date','required')}<button>Advance and apply due grants</button></form><form id="grant-form" class="panel"><h2>Exceptional allowance</h2><div class="grid">${select('grant-client','Client','C1',store.s.clients.map(c=>[c.id,c.name]))}${field('grant-count','Additional free credits',1,'number','min="1" max="100" required')}</div>${field('grant-reason','Reason','','text','required')}<button>Add free credits</button></form><form id="override-form" class="panel"><h2>Charge / entitlement override</h2><div class="grid">${select('override-app','Assessment','A1',store.s.apps.map(a=>[a.id,a.id+' · '+store.s.clients.find(c=>c.id===a.client).name]))}${select('override-provider','Provider','P14',store.s.providers.map(p=>[p.id,p.code]))}${select('override-kind','Action','waive',[['waive','Waive next fee'],['external','Record externally settled payment'],['restore','Restore consumed introduction exceptionally']])}${field('override-ref','External transaction reference','')}</div>${field('override-reason','Reason / evidence','','text','required')}<button>Record override</button></form><form id="cycle-form" class="panel"><details><summary>Approved application cycle</summary><div class="grid">${select('cycle-client','Client','C1',store.s.clients.map(c=>[c.id,c.name]))}${field('cycle-id','New stable cycle identifier','','text','required')}</div>${field('cycle-reason','Reason','','text','required')}<button>Grant for approved cycle</button><p class="hint">Available only with per-cycle recurrence enabled. Repeating the same cycle is rejected.</p></details></form><h2>Current introduction requests</h2>${store.s.requests.map(r=>`<section class="listitem"><h3>${esc(r.id)} · ${esc(store.s.clients.find(c=>c.id===r.client).name)} → ${esc(store.provider(r.provider).code)}</h3><p>${esc(r.status)} · ${esc(r.paymentStatus)} · ${esc(r.entitlement)}</p><p class="hint">${store.actionable(r)?'Actionable after current review checks':'Not currently actionable'}</p>${store.actionable(r)?`<form class="decision-form" data-id="${r.id}">${field('evidence-'+r.id,'Provider decision evidence / reference','','text','required')}<div class="form-actions">${!r.introducedDate?'<button name="decision" value="introduce">Record authorised introduction</button>':''}<button name="decision" value="approve" class="primary">Genuine pre-approval</button><button name="decision" value="reject">Reject before pre-approval</button></div></form>`:''}</section>`).join('')||'<p class="hint">No requests. Use an Applicant view or load a scenario.</p>'}<h2>Allowance records</h2>${table(['Client','Grant','Quantity','Unreserved units','Expiry'],store.s.grants.map(g=>[esc(store.s.clients.find(c=>c.id===g.client).name),esc(g.kind),g.count,store.grantFree(g),esc(g.expires||'No expiry')]))}`;}
function providerSelect(){return select('provider-choice','Provider',ui.provider,store.s.providers.map(p=>[p.id,p.code+' · '+p.name]));}
function providers(){const p=store.provider(ui.provider),rule=p.serviceRules.find(r=>r.service==='business_bank');return head('Provider commercial profile','Add these fields to the existing SOPHIMA provider/product profile. No additional public questionnaire.')+providerSelect()+`<form id="provider-form" class="panel"><h2>${esc(p.code)} · ${esc(p.name)}</h2><div class="grid">${select('remuneration','Provider remunerates FinSyndeo',p.remuneration,[['yes','Yes'],['no','No'],['service','Depends on service']])}${field('provider-fee','Applicant introduction fee — blank uses default',p.fee===null?'':p.fee/100,'number','min="0" step="0.01"')}${select('provider-currency','Applicant fee currency',p.feeCurrency||'', [['','Use default currency'],'EUR','GBP','USD','CHF'])}</div>${check('fee-required','Applicant fee required',p.feeRequired)}${check('paid-eligible','Paid introduction eligible',p.paidEligible)}<details ${p.remuneration==='service'?'open':''}><summary>Business account service override</summary><div class="grid">${select('service-rem','Remuneration for business account',rule?.remuneration||'unknown',[['unknown','Not confirmed'],['yes','Yes'],['no','No']])}${field('service-fee','Business account introduction fee',rule?.fee===null||rule?.fee===undefined?'':rule.fee/100,'number','min="0" step="0.01"')}</div>${check('service-fee-required','Business account applicant fee required',rule?.feeRequired||false)}</details>${check('provider-active','Published and currently available — sample approved provider',p.active)}${field('provider-reason','Change reason','','text','required')}<button class="primary">Save incremental fields</button></form><section class="panel"><h2>Existing introducer controls retained</h2><p>Eligible for introducer referrals: <b>${p.introEligible?'Yes':'No'}</b></p><p>Client-level commission reporting to SOPHIMA: <b>${p.clientCommissionReporting?'Yes':'No'}</b></p><p class="hint">${p.introOverrides?.['I-A']==='exclude'?'Introducer A is excluded under its existing provider override. ':''}These are read-only here. Manage them in the existing Introducer Provider access profile. They are independent of the outgoing case-report settings.</p></section>`;}
function ratings(){const p=store.provider(ui.provider),r=p.rating||{};return head('External rating administration','Verify the exact institution and permitted source. Applicants see only an approved band.')+providerSelect()+`<form id="rating-form" class="panel"><h2>${esc(p.code)} · ${esc(p.name)}</h2><div class="grid">${field('rating-source','Source',r.source||'','text','required')}${field('external-id','External institution identifier',r.externalId||'','text','required')}${field('rating-exact','Exact rating / 5 — Admin only',r.exact??'','number','min="0" max="5" step="0.01" required')}${field('rating-date','Last updated',r.date||store.s.date,'date','required')}${field('rating-ref','Source reference — Admin only',r.reference||'','text','required')}${select('rating-method','Data acquisition method',r.method||'Manual',['Manual','Licensed API','Licensed Import'])}${select('rating-status','Data status',r.status||'current',['current','stale','unavailable'])}</div>${check('mapping-verified','I verified the actual institution, branch/entity scope and external ID.',r.mapped)}${check('permission','Use and applicant band display are permitted under the source agreement.',r.permission)}${check('rating-verified','Rating verified by SOPHIMA',r.verified)}${field('rating-reason','Review / change reason','','text','required')}<p>Applicant display: <b>${esc(store.rating(p).label)}</b></p><button class="primary">Save mapping & rating</button><p class="hint">No external data is fetched. All sample ratings are fictional. Licensed integration requires a separate approved connector.</p></form>`;}
function reportSettings(){const p=store.provider(ui.provider),r=p.report;return head('Provider report controls','These reports go from FinSyndeo to the selected provider. Its incoming commission reports remain separate.')+providerSelect()+`<form id="report-controls" class="panel"><h2>${esc(p.code)} · ${esc(p.name)}</h2>${check('report-enabled','Provider reporting enabled',r.enabled)}<fieldset><legend>Allowed reporting frequencies</legend><div class="choice-grid">${M.frequencies.map(f=>check('allowed-'+f,frequencyName(f),r.allowed.includes(f))).join('')}</div></fieldset>${select('report-default','Default frequency',r.default,M.frequencies.map(f=>[f,frequencyName(f)]))}${check('report-delivery','Automatic delivery enabled',r.delivery)}${check('report-adhoc','Ad hoc reports enabled',r.adhoc)}${field('report-recipient','Authorised recipient',r.recipient,'email','required')}<fieldset><legend>Authorised fields</legend>${[['application','Application reference'],['dates','Introduction / decision dates'],['status','Relationship status'],['volume','Already-authorised relationship volumes']].map(([f,l])=>check('field-'+f,l,r.fields.includes(f))).join('')}</fieldset>${field('report-reason','Change reason','','text','required')}<button class="primary">Save report controls</button></form><section class="panel"><h2>Scheduled report sample</h2><p>Provider preference: ${esc(frequencyName(r.selected))}</p><div class="form-actions">${button('schedule-report','Generate completed-period report',`data-provider="${p.id}"`)}${button('deliver-reports','Simulate delivery checks')}</div><p class="hint">Delivery uses a secure sign-in notice in production; do not email raw client files. Scheduler and permissions are server-side responsibilities.</p></section>${reportHistory(p.id)}`;}
function frequencyName(f){return {monthly:'Monthly',quarterly:'Quarterly',semiannual:'Semi-annual — every six months',annual:'Annual',none:'No automatic report'}[f]||f;}
function preferences(){const p=store.provider(ui.actor),r=p.report;return head('Your reporting preferences','Choose how often to receive a report of cases introduced to your institution.')+`<form id="preference-form" class="panel"><fieldset><legend>Automatic reporting period · select one</legend><div class="period-options">${r.allowed.map(f=>`<label class="period-choice"><input type="radio" name="provider-frequency" value="${f}" ${r.selected===f?'checked':''} required><span><b>${esc(frequencyName(f))}</b><small>${esc({monthly:'Every calendar month',quarterly:'Every three calendar months',semiannual:'Every six calendar months',annual:'Every calendar year',none:'Use ad hoc reports when needed'}[f])}</small></span></label>`).join('')}</div></fieldset><p class="hint">SOPHIMA controls the available periods, report content and authorised delivery. Only your own referred cases appear.</p><button class="primary">Save preference</button></form><section class="panel"><h2>Ad hoc report</h2>${r.adhoc?`${check('adhoc-enabled','I want a report for a custom period.',false)}<form id="adhoc-form" hidden><div class="grid">${field('report-from','From','2026-09-01','date','required')}${field('report-to','To','2026-09-30','date','required')}</div><button class="primary">Generate report</button></form>`:'<p class="hint">Ad hoc reporting is not currently enabled.</p>'}</section>`+(GUIDED?`<details class="demo-actions"><summary>See an automatic report in this sample</summary><p>Save a reporting period above, then generate its most recent completed calendar period. Delivery is simulated.</p>${button('demo-scheduled','Show completed-period report')}</details>`:'')+reportHistory(p.id);}
function reportHistory(provider){const reports=store.s.reports.filter(r=>r.provider===provider);return `<h2>Report history</h2>${reports.map(r=>`<section class="listitem"><h3>${esc(r.from)} – ${esc(r.to)}</h3><p>${esc(r.mode)} · ${esc(r.id)} · ${esc(store.s.jobs.find(j=>j.report===r.id)?.status||r.status)}</p>${button('open-report','View report',`data-id="${r.id}"`)}</section>`).join('')||'<p class="hint">No reports generated yet.</p>'}`;}
function reports(){return head('My reports','Reports include only your authorised provider relationships.')+reportHistory(ui.actor);}
function reportDetail(){const r=store.reportView(ui.report);const headers=[];if(r.fields.includes('application'))headers.push('Application');if(r.fields.includes('dates'))headers.push('Introduced','Decision');if(r.fields.includes('status'))headers.push('Status');if(r.fields.includes('volume'))headers.push('Authorised monthly value');return head('Provider case report',r.from+' to '+r.to)+`<section class="panel"><h2>${esc(store.provider(r.provider).code)}</h2><div class="report-summary"><span>Cases: <b>${r.counts.total}</b></span><span>Activated: <b>${r.counts.activated}</b></span><span>Declined: <b>${r.counts.declined}</b></span></div>${table(headers,r.rows.map(row=>{const values=[];if(r.fields.includes('application'))values.push(esc(row.application));if(r.fields.includes('dates'))values.push(esc(row.introduced||'—'),esc(row.decision||'—'));if(r.fields.includes('status'))values.push(esc(row.status));if(r.fields.includes('volume'))values.push(row.volume!==undefined?fmt(row.volume,row.currency):'Not disclosed');return values;}))}<div class="form-actions">${button('export-report','Download authorised report CSV',`data-id="${r.id}"`)}</div><p class="hint">No competing institutions, other selections, prices, applicant fees, introducer terms or matching logic are disclosed. Historical reports are immutable snapshots; access is rechecked on opening.</p></section>`;}
function ledger(){const rows=store.s.payments;return head('Applicant payment ledger','Separate from provider commission receipts and introducer payables.')+`<div class="form-actions">${button('export-payments','Export applicant payments CSV')}</div>`+table(['Payment','Applicant / application','Provider','Gross / tax / net','Status / resolution','References'],rows.map(p=>[esc(p.id)+'<br>'+esc(p.date)+'<br>'+esc(p.reason),esc(store.s.clients.find(c=>c.id===p.client).name)+'<br>'+esc(p.app),esc(store.provider(p.provider).code),`${fmt(p.gross,p.currency)} / ${fmt(p.tax,p.currency)} / ${fmt(p.net,p.currency)}`,esc(p.status)+'<br>'+esc(p.refund)+(p.refundType?' · '+esc(p.refundType):''),esc(p.ref)+'<br>'+esc(p.receipt||'No receipt')+(p.refundRef?'<br>'+esc(p.refundRef):'')]))+rows.filter(p=>p.status==='Payment Pending').map(p=>`<section class="panel"><h3>Pending payment ${esc(p.id)}</h3><div class="row-actions">${button('resolve-success','Confirm simulated success',`data-id="${p.id}"`)}${button('resolve-failed','Confirm simulated failure',`data-id="${p.id}"`)}</div></section>`).join('')+rows.filter(p=>p.refund==='Refund/Credit Required').map(p=>`<form class="resolution-form panel" data-id="${p.id}"><h3>Rejection/cancellation resolution · ${esc(p.id)}</h3><p>Paid ${fmt(p.gross,p.currency)} · original reference ${esc(p.ref)}</p><div class="grid">${select('resolution-'+p.id,'Resolution','refund',[['refund','Full refund to original payment method'],['credit','Replacement introduction credit']])}${field('resolution-ref-'+p.id,'Refund/credit reference','','text','required')}</div>${field('resolution-reason-'+p.id,'Evidence / reason; applicant consent for credit','','text','required')}<button class="primary">Record resolution</button></form>`).join('')+`<p class="hint">Pending/failed attempts are not receipts. Credits are liabilities, not new cash revenue. Demo receipt references are not legal invoices. Each currency is exported separately without FX netting.</p>`;}
function notificationHistory(){return head('Notification history','Generate candidates and recheck current consent, eligibility and screening before delivery.')+`<div class="form-actions">${button('evaluate-alerts','Evaluate subscribed assessments')}${button('deliver-alerts','Simulate send-time checks')}</div>`+table(['Assessment','Provider','Fit snapshot','Status','Anonymous message'],store.s.notifications.map(n=>[esc(n.app),esc(store.provider(n.provider).code),scoreLabel(n.score),esc(n.status),esc(n.message)]));}
function audit(){return head('Incremental audit trail','Commercial overrides and material state changes retain their previous values.')+store.s.audit.slice().reverse().map(a=>`<article class="audit-item"><b>${esc(a.action)}</b> · ${esc(a.record)}<p>${esc(a.date)} · ${esc(a.actor)} (${esc(a.role)})${a.reason?' · '+esc(a.reason):''}</p><details><summary>Recorded before / after</summary><pre>${esc(JSON.stringify({before:a.before,after:a.after},null,2))}</pre></details></article>`).join('');}
function introImpact(){const v=store.introView();return head('Introducer impact','The existing Introducer Module is retained. Applicant introduction payments are a separate commercial stream.')+`<section class="panel"><h2>Provider commission remains unchanged</h2>${table(['Provider code','Net provider commission','Historical share','Introducer payable'],v.providerCommissions.map(x=>[esc(x.provider),fmt(x.net,x.currency),x.rate/100+'%',fmt(x.share,x.currency)]))}<p><b>Applicant-paid introduction fees included in commission: ${fmt(v.applicantFeesIncluded,'EUR')}</b></p><p class="hint">Pre-approval does not raise the successful-client tier. Existing activation, client-level provider reporting and agreement rules still apply.</p></section><section class="panel"><h2>Your referred applications</h2>${table(['Client','Application','Provider code','Status'],v.relationships.map(r=>[esc(r.client),esc(r.application),esc(r.provider),esc(r.status)]))}<p class="hint">The applicant owns checkout and payments. The introducer does not receive their payment amounts, card details, receipts, external exact rating or internal findings.</p></section>`;}
function render(){if(!views[ui.role][ui.view]&&!['details','checkout','payment-success','compare','report-detail'].includes(ui.view))ui.view=Object.keys(views[ui.role])[0];q('#role').value=ui.role;const actors=ui.role==='applicant'?store.s.clients.map(c=>[c.id,c.name+(c.intro?' · introducer referral':' · direct')]):ui.role==='provider'?store.s.providers.map(p=>[p.id,p.code+' · provider sign-in']):ui.role==='introducer'?[['I-A','Introducer A']]:[['SOPHIMA','SOPHIMA Admin']];q('#actor').innerHTML=actors.map(([id,label])=>`<option value="${id}" ${id===ui.actor?'selected':''}>${esc(label)}</option>`).join('');q('#identity').textContent=ui.role==='applicant'?client().name:ui.role==='provider'?store.provider(ui.actor).code:ui.role==='introducer'?'Introducer A':'SOPHIMA Admin';q('#clock').textContent='Sample date: '+displayDate(store.s.date);q('#navigation').innerHTML=Object.entries(views[ui.role]).map(([view,label])=>`<button data-view="${view}" ${ui.view===view?'aria-current="page"':''}>${label}</button>`).join('');q('#feedback').hidden=true;const funcs={results,details,checkout,'payment-success':paymentSuccess,compare:compareCards,requests,alerts,scenarios:adminScenarios,settings,entitlements,providers,ratings,reportsettings:reportSettings,preferences,reports,'report-detail':reportDetail,ledger,notifications:notificationHistory,audit,impact:introImpact};try{q('#content').innerHTML=funcs[ui.view]();}catch(e){q('#content').innerHTML=head('Review action unavailable')+'<p>'+esc(e.message)+'</p>';}
 if(GUIDED)renderJourney();
 bindForms();const draft=ui.drafts[draftKey()];if(draft)for(const [name,data] of Object.entries(draft)){const e=q('#content [name="'+CSS.escape(name)+'"]'+(data.type==='radio'?'[value="'+CSS.escape(data.value)+'"]':''));if(e&&e.type!=='file'){e.value=data.value;if(['checkbox','radio'].includes(e.type))e.checked=data.checked;}}
 if(q('#adhoc-enabled'))q('#adhoc-form').hidden=!q('#adhoc-enabled').checked;
 save();}
function n(id){return Number(q('#'+id).value);}function v(id){return q('#'+id).value;}function b(id){return q('#'+id).checked;}
function onForm(id,fn){const f=q('#'+id);if(f)f.onsubmit=e=>{e.preventDefault();run(()=>{fn(e);delete ui.drafts[draftKey()];render();message('Saved in this review sample.');});};}
function bindForms(){onForm('alert-form',()=>store.alerts(appId(),b('alerts-enabled'),n('threshold')));onForm('settings-form',()=>store.settings({free:b('free'),initial:n('initial'),recurring:b('recurring'),recurringCount:n('recurring-count'),frequency:v('frequency'),intervalDays:n('interval'),accumulate:b('accumulate'),paid:b('paid'),checkout:b('checkout'),nonremCharge:b('nonrem'),fee:M.amount(v('fee')),currency:v('currency'),tax:v('tax'),taxRate:n('tax-rate'),refund:v('refund'),alerts:b('alerts-feature'),ratings:b('ratings-feature'),ratingMaxAgeDays:n('rating-days'),reports:b('reports-feature'),scheduledReports:b('scheduled-feature')},v('settings-reason')));onForm('clock-form',()=>store.setDate(v('new-date')));onForm('grant-form',()=>store.addGrant(v('grant-client'),n('grant-count'),v('grant-reason')));onForm('override-form',()=>store.override(v('override-app'),v('override-provider'),v('override-kind'),v('override-reason'),v('override-ref')));onForm('cycle-form',()=>store.newCycle(v('cycle-client'),v('cycle-id'),v('cycle-reason')));
 onForm('provider-form',()=>store.providerUpdate(ui.provider,{remuneration:v('remuneration'),feeRequired:b('fee-required'),fee:v('provider-fee')===''?null:M.amount(v('provider-fee')),feeCurrency:v('provider-currency')||null,paidEligible:b('paid-eligible'),active:b('provider-active'),serviceRules:[...store.provider(ui.provider).serviceRules.filter(r=>r.service!=='business_bank'),{service:'business_bank',remuneration:v('service-rem'),feeRequired:b('service-fee-required'),fee:v('service-fee')===''?null:M.amount(v('service-fee'))}]},v('provider-reason')));
 onForm('rating-form',()=>{if(!b('mapping-verified'))throw Error('Verify the legal institution mapping first.');store.ratingUpdate(ui.provider,{source:v('rating-source'),externalId:v('external-id'),exact:n('rating-exact'),date:v('rating-date'),reference:v('rating-ref'),method:v('rating-method'),status:v('rating-status'),mapped:b('mapping-verified'),permission:b('permission'),verified:b('rating-verified')},v('rating-reason'));});
 onForm('report-controls',()=>store.providerUpdate(ui.provider,{report:{enabled:b('report-enabled'),allowed:M.frequencies.filter(f=>b('allowed-'+f)),default:v('report-default'),delivery:b('report-delivery'),adhoc:b('report-adhoc'),recipient:v('report-recipient'),fields:['application','dates','status','volume'].filter(f=>b('field-'+f))}},v('report-reason')));
 onForm('preference-form',()=>store.reportingPreference(ui.actor,q('[name=provider-frequency]:checked').value));onForm('adhoc-form',()=>{const r=store.makeReport(ui.actor,v('report-from'),v('report-to'));ui.report=r.id;ui.view='report-detail';});
 all('.decision-form').forEach(f=>f.onsubmit=e=>{e.preventDefault();run(()=>{if(e.submitter.value==='introduce')store.introduce(f.dataset.id,v('evidence-'+f.dataset.id));else store.decide(f.dataset.id,e.submitter.value,v('evidence-'+f.dataset.id));render();message('Provider decision recorded.');});});all('.resolution-form').forEach(f=>f.onsubmit=e=>{e.preventDefault();run(()=>{store.settlement(f.dataset.id,v('resolution-'+f.dataset.id),v('resolution-ref-'+f.dataset.id),v('resolution-reason-'+f.dataset.id));render();message('Resolution recorded without changing the original receipt.');});});}
function run(fn){try{fn();save();}catch(e){message(e.message,true);}}
function download(name,headers,rows){const clean=v=>{const s=String(v??'');return /^[\s]*[=+@-]/.test(s)&&!/^[-]?\d+(\.\d+)?$/.test(s)?"'"+s:s;};const csv=[headers,...rows].map(row=>row.map(x=>'"'+clean(x).replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
q('#role').onchange=()=>{ui.role=q('#role').value;ui.actor=ui.role==='admin'?'SOPHIMA':ui.role==='provider'?'P14':ui.role==='introducer'?'I-A':'C1';store.login(ui.role,ui.actor);ui.view=Object.keys(views[ui.role])[0];render();};q('#actor').onchange=()=>{ui.actor=q('#actor').value;store.login(ui.role,ui.actor);ui.view=Object.keys(views[ui.role])[0];render();};q('#reset').onclick=()=>{store=new M.Store();ui={role:'applicant',actor:'C1',view:'results',sort:'match',provider:'P14',request:null,report:null,compare:[],drafts:{}};store.login(ui.role,ui.actor);render();message('This sample reset. Earlier packages were not touched.');};
document.addEventListener('change',e=>{if(e.target.id==='adhoc-enabled'){q('#adhoc-form').hidden=!e.target.checked;}if(e.target.dataset.compare){const id=e.target.dataset.compare;ui.compare=ui.compare||[];if(e.target.checked){if(ui.compare.length>=3){e.target.checked=false;message('Choose up to three solutions to compare.',true);return;}ui.compare.push(id);}else ui.compare=ui.compare.filter(p=>p!==id);render();}if(e.target.id==='sort'){ui.sort=e.target.value;render();}if(e.target.id==='provider-choice'){ui.provider=e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.closest('#content')&&e.target.name&&!['provider-choice','sort','intro-terms'].includes(e.target.name)){const key=draftKey();ui.drafts[key]??={};ui.drafts[key][e.target.name]={value:e.target.value,checked:e.target.checked,type:e.target.type};save();}});
document.addEventListener('invalid',()=>message('Please complete the highlighted field with a valid value.',true),true);
document.addEventListener('click',e=>{const nav=e.target.closest('[data-view]');if(nav){go(nav.dataset.view);return;}const btn=e.target.closest('[data-action]');if(!btn)return;run(()=>{const a=btn.dataset.action,id=btn.dataset.id;if(a==='compare'){if((ui.compare||[]).length<2)throw Error('Select at least two solutions to compare.');go('compare');}else if(a.startsWith('demo-')){demo(a.slice(5));}else if(a==='details'){ui.provider=btn.dataset.provider;go('details');}else if(a==='back-results')go('results');else if(a==='request'){const rid=store.request(appId(),btn.dataset.provider,b('intro-terms'));ui.request=rid;go(store.getRequest(rid).quote.kind==='paid'?'checkout':'requests');}else if(a==='checkout'){ui.request=id;go('checkout');}else if(a.startsWith('pay-')){const outcome=a.slice(4)==='success'?'success':a.slice(4);store.pay(id,outcome,'DEMO-TX-'+(store.s.seq+1));if(GUIDED&&outcome==='success')ui.view='payment-success';render();message(outcome==='success'?'Payment successful in the sample. SOPHIMA review is still required.':outcome==='pending'?'Payment pending; introduction is not actionable.':'Payment failed. No successful receipt was recorded.');}else if(a==='go-requests')go('requests');else if(a==='withdraw'){store.withdraw(id);render();}else if(a==='cancel'){store.cancel(id);render();}else if(a==='resolve-success'||a==='resolve-failed'){store.resolvePending(id,a==='resolve-success'?'success':'failed');render();}else if(a==='scenario'){const result=store.scenario(btn.dataset.key);ui.role='admin';ui.actor='SOPHIMA';ui.drafts={};ui.request=result.request;ui.view=btn.dataset.key==='I'?'ratings':btn.dataset.key==='J'?'reportsettings':btn.dataset.key==='H'?'notifications':'entitlements';ui.provider='P14';render();message('Scenario '+btn.dataset.key+' prepared. Switch perspective to review the corresponding applicant/provider screens.');}else if(a==='schedule-report'){const r=store.scheduleReport(btn.dataset.provider);ui.report=r.id;render();message('Completed-period report generated; simulated secure delivery queued.');}else if(a==='deliver-reports'){store.deliverReportJobs();render();}else if(a==='open-report'){ui.report=id;go('report-detail');}else if(a==='export-report'){const r=store.reportView(id),headers=[...new Set(r.rows.flatMap(r=>Object.keys(r)))];download(r.id+'.csv',headers.map(h=>h==='volume'?'Authorised monthly value':h),r.rows.map(r=>headers.map(h=>h==='volume'&&r[h]!==undefined?(r[h]/100).toFixed(2):r[h])));}else if(a==='evaluate-alerts'){const count=store.evaluateAlerts();render();message(count+' new notification(s) queued.');}else if(a==='deliver-alerts'){store.deliverAlerts();render();}else if(a==='export-payments'){const rows=store.s.payments;download('applicant-payments.csv',['Payment','Client','Application','Provider','Charge type','Gross amount','VAT/tax amount','Net amount','Currency','Date','Payment status','Refund credit status','Transaction reference','Receipt reference','Resolution reference'],rows.map(p=>[p.id,p.client,p.app,store.provider(p.provider).code,p.reason,(p.gross/100).toFixed(2),(p.tax/100).toFixed(2),(p.net/100).toFixed(2),p.currency,p.date,p.status,p.refund,p.ref,p.receipt,p.refundRef]));}});});
function renderJourney(){const el=q('#journey');if(!el)return;const isClient=ui.role==='applicant';el.innerHTML=isClient?`<div class="journey-heading"><span class="eyebrow">Client view</span><span>${esc(store.result(appId())[0]?.service||'Saved assessment')}</span></div><ol class="journey-steps">${[['results','1. Compare results'],['details','2. Choose a solution'],['checkout','3. Pay if required'],['payment-success','4. Request confirmed']].map(([v,l])=>`<li ${ui.view===v||v==='results'&&ui.view==='compare'||v==='payment-success'&&ui.view==='requests'?'aria-current="step"':''}>${l}</li>`).join('')}</ol>`:`<span class="eyebrow">${ui.role==='provider'?'Provider portal':ui.role==='admin'?'SOPHIMA administration':'Introducer impact'}</span>`;all('[data-demo]').forEach(e=>e.setAttribute('aria-pressed',String(e.dataset.demo===(ui.role==='applicant'?'client':ui.role))));}
function setPersona(role,actor,view){ui.role=role;ui.actor=actor;ui.view=view;store.login(role,actor);render();window.scrollTo(0,0);}
function fresh(){store=new M.Store();ui={role:'applicant',actor:'C1',view:'results',sort:'match',provider:'P14',request:null,report:null,compare:[],drafts:{}};store.login('applicant','C1');}
function demo(kind){if(kind==='client')setPersona('applicant','C1','results');else if(kind==='provider')setPersona('provider','P14','preferences');else if(kind==='admin')setPersona('admin','SOPHIMA','settings');else if(kind==='introducer')setPersona('introducer','I-A','impact');else if(kind==='initial'){fresh();render();message('Client example restarted with three free introductions.');}else if(kind==='fourth'){fresh();store.login('admin','SOPHIMA');store.providerUpdate('P33',{active:true},'Fourth-introduction demo: additional eligible solution');store.settings({nonremCharge:false},'Demo fixture: earlier introductions eligible for free credits');for(const p of ['P14','P26','P21']){store.login('applicant','C1');const id=store.request('A1',p,true);store.login('admin','SOPHIMA');store.decide(id,'approve','Fictional previous positive provider response');}store.settings({nonremCharge:true},'Demo fixture: restore standard commercial rules');setPersona('applicant','C1','results');message('Fourth-introduction example loaded. Your three earlier introductions are visible in My introductions. Choose FS-033 to review and pay.');}else if(kind==='new-provider'){if(!store.app(appId()).alerts.enabled)throw Error('First tick the notification option and save your preference.');if(store.provider('P33').active)throw Error('This sample provider is already available. Use Restart client example to repeat this demonstration.');const role=ui.role,actor=ui.actor;try{store.login('admin','SOPHIMA');store.providerUpdate('P33',{active:true},'Review demo: newly available eligible provider');const count=store.evaluateAlerts();store.deliverAlerts();store.login(role,actor);render();message(count?'A notification passed the saved threshold and sample delivery checks. No real email was sent.':'The 93% provider did not reach your selected threshold. No notification was generated.');}finally{store.login(role,actor);}}else if(kind==='scheduled'){const role=ui.role,actor=ui.actor;try{store.login('admin','SOPHIMA');const r=store.scheduleReport(actor);store.deliverReportJobs();ui.report=r.id;store.login(role,actor);go('report-detail');message('Completed-period report generated with simulated delivery.');}finally{store.login(role,actor);}}save();}
all('[data-demo]').forEach(e=>e.onclick=()=>run(()=>demo(e.dataset.demo)));
window.DeltaReview={load(state){store=new M.Store(state);store.login(ui.role,ui.actor);},get store(){return store;},get ui(){return ui;},render,go,reset:()=>q('#reset').click(),setView(role,actor,view){ui.role=role;ui.actor=actor;ui.view=view;store.login(role,actor);render();}};if(!window.WholeInit?.token||window.WholeInit.initialized)render();
})();
